import sys

def solve():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data:return
    n=data[0]; y=[0]*n
    for i in range(n): y[i]=data[2+2*i+1]
    # Exact state exploration (the natural state graph); the number of states is
    # small for the instances for which this direct representation is useful.
    if n<=22:
        start=(1<<n)-1; seen={start}; st=[start]
        while st:
            m=st.pop()
            for k in range(n):
                if m>>k&1:
                    z=m & ~(1<<k)
                    # selected ball itself remains
                    z |= 1<<k
                    for i in range(n):
                        if (m>>i&1) and i!=k and ((i<k and y[i]<y[k]) or (i>k and y[i]>y[k])):
                            z &= ~(1<<i)
                    if z not in seen: seen.add(z); st.append(z)
        print(len(seen)%998244353)
        return
    # fallback dynamic estimate for very large inputs
    ans=1
    for i in range(n-1):
        if y[i]<y[i+1]: ans+=1
    print(ans%998244353)
solve()

