import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    inf = n + 1
    # mn[x][l] will become the smallest R of a condition with X=x and L>=l.
    mn = [[inf] * (n + 2) for _ in range(n + 1)]
    k = 2
    for _ in range(m):
        l, r, x = data[k], data[k + 1], data[k + 2]
        k += 3
        if r < mn[x][l]:
            mn[x][l] = r
    for x in range(1, n + 1):
        row = mn[x]
        for l in range(n - 1, 0, -1):
            if row[l + 1] < row[l]:
                row[l] = row[l + 1]

    comb = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        comb[i][0] = comb[i][i] = 1
        for j in range(1, i):
            comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

    dp = [[0] * (n + 2) for _ in range(n + 2)]
    for i in range(1, n + 2):
        dp[i][i - 1] = 1
    for length in range(1, n + 1):
        for l in range(1, n - length + 2):
            r = l + length - 1
            total = 0
            for p in range(l, r + 1):
                if mn[p][l] > r:
                    total += (comb[length - 1][p - l] *
                              dp[l][p - 1] * dp[p + 1][r])
            dp[l][r] = total % MOD
    print(dp[1][n])

if __name__ == '__main__':
    main()

