    d=list(map(int,sys.stdin.buffer.read().split()))
    if not d:return
    n,m=d[0],d[1]; a=[x-1 for x in d[2:]]
    ch=[[] for _ in range(n)]; indeg=[0]*n
    for i,p in enumerate(a): ch[p].append(i); indeg[p]+=1
    q=[i for i in range(n) if indeg[i]==0]; order=[]
    for v in q:
        order.append(v); p=a[v]; indeg[p]-=1
        if indeg[p]==0:q.append(p)
    dp=[None]*n
    for v in order:
        kids=ch[v]
        if not kids:
            dp[v]=array('I',[0])+array('I',range(1,m+1))
        elif len(kids)==1:
            old=dp[kids[0]]; cur=array('I',[0]); s=0
            for k in range(1,m+1):
                s+=old[k]
                if s>=MOD:s-=MOD
                cur.append(s)
            dp[v]=cur
        else:
            cur=array('I',[0])
            for k in range(1,m+1):
                z=1
                for u in kids:z=z*dp[u][k]%MOD
                cur.append((cur[k-1]+z)%MOD)
            dp[v]=cur
    ans=1; seen=set()
    for s in range(n):
        if indeg[s] and s not in seen:
            cyc=[]; v=s
            while v not in seen:
                seen.add(v);cyc.append(v);v=a[v]
            total=0
            for k in range(1,m+1):
                z=1
                for r in cyc:
                    for u in ch[r]:
                        if dp[u] is not None:z=z*dp[u][k]%MOD
                total=(total+z)%MOD
            ans=ans*total%MOD
    print(ans)
