import sys

MOD = 998244353

def factor(x):
    r = {}
    d = 2
    while d * d <= x:
        while x % d == 0:
            r[d] = r.get(d, 0) + 1
            x //= d
        d += 1
    if x > 1:
        r[x] = r.get(x, 0) + 1
    return r

def contribution(p, exps):
    total = sum(exps)
    powers = [1] * (total + 1)
    for i in range(1, total + 1):
        powers[i] = powers[i-1] * p % MOD
    dp = {0: 1}
    for i, e in enumerate(exps, 1):
        nd = {}
        if e == 0:
            for d, v in dp.items():
                nd[d] = v * powers[d] % MOD
        else:
            for d, v in dp.items():
                z = d + e
                w = v * powers[z] % MOD
                nd[z] = (nd.get(z, 0) + w) % MOD
                if d >= e:
                    z = d - e
                    w = v * powers[z] % MOD
                else:
                    z = 0
                    w = v * pow(p, (e-d) * i, MOD) % MOD
                nd[z] = (nd.get(z, 0) + w) % MOD
        dp = nd
    return sum(dp.values()) % MOD

data = list(map(int, sys.stdin.buffer.read().split()))
n = data[0]
a = data[1:]
fac = [factor(x) for x in a]
primes = set()
for f in fac:
    primes.update(f)
answer = 1
for p in primes:
    answer = answer * contribution(p, [f.get(p, 0) for f in fac]) % MOD
print(answer)

