import sys

MOD = 998244353
MAXA = 100000

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    a = data[1:1+n]

    spf = list(range(MAXA + 1))
    for p in range(2, 317):
        if spf[p] == p:
            for v in range(p * p, MAXA + 1, p):
                if spf[v] == v:
                    spf[v] = p

    phi = list(range(MAXA + 1))
    for p in range(2, MAXA + 1):
        if spf[p] == p:
            for v in range(p, MAXA + 1, p):
                phi[v] -= phi[v] // p

    stored = [0] * (MAXA + 1)
    divisor_cache = {}
    answers = []
    total = 0
    weight = 1

    for x in a:
        divisors = divisor_cache.get(x)
        if divisors is None:
            divisors = [1]
            y = x
            while y > 1:
                p = spf[y]
                e = 0
                while y % p == 0:
                    y //= p
                    e += 1
                base = divisors[:]
                power = 1
                for _ in range(e):
                    power *= p
                    divisors.extend(d * power for d in base)
            divisor_cache[x] = divisors

        added = 0
        for d in divisors:
            added += phi[d] * stored[d]
            v = stored[d] + weight
            if v >= MOD:
                v -= MOD
            stored[d] = v

        total = (2 * total + added) % MOD
        answers.append(str(total))
        weight = (weight * 2) % MOD

    sys.stdout.write('\n'.join(answers))

if __name__ == '__main__':
    main()

