MOD=998244353

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data:return
    n=data[0]; a=data[1:]
    M=100000
    spf=list(range(M+1))
    for i in range(2, int(M**0.5)+1):
        if spf[i]==i:
            for j in range(i*i,M+1,i):
                if spf[j]==j: spf[j]=i
    phi=list(range(M+1));
    for i in range(2,M+1):
        if spf[i]==i:
            for j in range(i,M+1,i): phi[j]-=phi[j]//i
    cache={}
    F=[0]*(M+1)
    out=[]; ans=0; w=1
    for x in a:
        ds=cache.get(x)
        if ds is None:
            ds=[1]; y=x
            while y>1:
                p=spf[y]; q=1
                while y%p==0:y//=p;q*=p
                old=ds[:]
                mul=1
                for _ in range(1, q):
                    mul*=p
                    ds += [d*mul for d in old]
            cache[x]=ds
        s=0
        for d in ds:s += phi[d]*F[d]
        ans=(2*ans+s)%MOD
        out.append(str(ans))
        for d in ds:F[d]=(F[d]+w)%MOD
        w=w*2%MOD
    print('\n'.join(out))
