class Solution:
    def maxSubarrays(self, n: int, conflictingPairs):
        by_right = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            by_right[b].append((a, i))

        count = [0] * (n + 1)
        id_at = [-1] * (n + 1)
        gain = [0] * len(conflictingPairs)
        largest = 0
        second = 0
        base = 0

        for right in range(1, n + 1):
            for left, idx in by_right[right]:
                count[left] += 1
                id_at[left] = idx
                if left > largest:
                    second = largest
                    largest = left
                elif left > second:
                    second = left

            base += right - largest
            if largest and count[largest] == 1:
                gain[id_at[largest]] += largest - second

        return base + max(gain)

