import sys


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    n = next(it)
    m = next(it)
    q = next(it)

    edges = []
    for _ in range(m):
        a = next(it) - 1
        b = next(it) - 1
        c = next(it)
        edges.append((a, b, c))

    queries = []
    ever_closed = [False] * m
    for _ in range(q):
        typ = next(it)
        if typ == 1:
            road = next(it) - 1
            queries.append((1, road))
            ever_closed[road] = True
        else:
            x = next(it) - 1
            y = next(it) - 1
            queries.append((2, x, y))

    INF = 10 ** 30
    dist = [[INF] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for i, (a, b, c) in enumerate(edges):
        if not ever_closed[i] and c < dist[a][b]:
            dist[a][b] = c
            dist[b][a] = c

    for k in range(n):
        row_k = dist[k]
        for i in range(n):
            d_ik = dist[i][k]
            if d_ik == INF:
                continue
            row_i = dist[i]
            for j in range(n):
                value = d_ik + row_k[j]
                if value < row_i[j]:
                    row_i[j] = value

    answers = []
    for query in reversed(queries):
        if query[0] == 2:
            value = dist[query[1]][query[2]]
            answers.append(str(value if value < INF else -1))
        else:
            a, b, c = edges[query[1]]
            from_a = [dist[i][a] for i in range(n)]
            from_b = [dist[i][b] for i in range(n)]
            to_a = dist[a][:]
            to_b = dist[b][:]
            for i in range(n):
                row = dist[i]
                da = from_a[i]
                db = from_b[i]
                for j in range(n):
                    value = da + c + to_b[j]
                    other = db + c + to_a[j]
                    if other < value:
                        value = other
                    if value < row[j]:
                        row[j] = value

    sys.stdout.write("\n".join(reversed(answers)))


if __name__ == "__main__":
    main()

