import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, budget = data[0], data[1]
    machines = [tuple(data[2 + 4*i: 6 + 4*i]) for i in range(n)]

    def feasible(cap):
        total = 0
        for a, p, b, q in machines:
            max_s = (cap + a - 1) // a
            best = 10**30

            # For a fixed residue of the number of S machines modulo b,
            # the cost is linear while T machines are still needed.
            for s in range(min(b, max_s + 1)):
                t = max(0, (cap - a*s + b - 1) // b)
                best = min(best, p*s + q*t)

            # Include the end of the positive-T region and max_s itself.
            for s in range(max(0, max_s - b), max_s + 1):
                t = max(0, (cap - a*s + b - 1) // b)
                best = min(best, p*s + q*t)

            total += best
            if total > budget:
                return False
        return True

    lo, hi = 0, 100 * budget + 1
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid
    print(lo)

if __name__ == '__main__':
    main()

