import sys
import heapq


def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    n = int(data[0])
    rows = [x.decode() for x in data[1:]]
    m = n * n
    inf = 10**9
    # The first m states are ordinary (left endpoint, right endpoint).
    # The other states are (character, left endpoint, right endpoint),
    # representing that the left matching edge has already been chosen.
    dist = [inf] * (27 * m)
    heap = []
    incoming = [[] for _ in range(n)]
    outgoing = [[[] for _ in range(26)] for _ in range(n)]

    for i in range(n):
        for j, ch in enumerate(rows[i]):
            if ch != '-':
                c = ord(ch) - 97
                incoming[j].append((i, c))
                outgoing[i][c].append(j)
                s = i * n + j
                if dist[s] > 1:
                    dist[s] = 1
                    heapq.heappush(heap, (1, s))

    for i in range(n):
        s = i * n + i
        dist[s] = 0
        heapq.heappush(heap, (0, s))

    while heap:
        cur, s = heapq.heappop(heap)
        if cur != dist[s]:
            continue
        if s < m:
            u, v = divmod(s, n)
            nd = cur + 1
            for x, c in incoming[u]:
                t = m + (c * n + x) * n + v
                if nd < dist[t]:
                    dist[t] = nd
                    heapq.heappush(heap, (nd, t))
        else:
            q = s - m
            c, xv = divmod(q, n * n)
            x, v = divmod(xv, n)
            nd = cur + 1
            for y in outgoing[v][c]:
                t = x * n + y
                if nd < dist[t]:
                    dist[t] = nd
                    heapq.heappush(heap, (nd, t))

    out = []
    for i in range(n):
        out.append(' '.join(str(-1 if dist[i*n+j] == inf else dist[i*n+j])
                            for j in range(n)))
    sys.stdout.write('\n'.join(out))


if __name__ == '__main__':
    main()

