    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    rows = [0] * n
    k = 2
    for _ in range(m):
        u, v = data[k] - 1, data[k + 1] - 1
        k += 2
        rows[u] ^= 1 << v
        rows[v] ^= 1 << u

    pivots = []
    rank = 0
    for col in range(n):
        chosen = -1
        for i in range(rank, n):
            if (rows[i] >> col) & 1:
                chosen = i
                break
        if chosen < 0:
            continue
        rows[rank], rows[chosen] = rows[chosen], rows[rank]
        for i in range(n):
            if i != rank and ((rows[i] >> col) & 1):
                rows[i] ^= rows[rank]
        pivots.append(col)
        rank += 1

    pivot_set = set(pivots)
    free = [c for c in range(n) if c not in pivot_set]
    basis = []
    for f in free:
        vec = 1 << f
        for r, c in enumerate(pivots):
            if (rows[r] >> f) & 1:
                vec |= 1 << c
        basis.append(vec)

    chosen_for_vertex = []
