from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid)
        m = len(grid[0])
        size = n * m
        dirs = [(-1, 1), (1, 1), (1, -1), (-1, -1)]

        straight = [[bytearray(size) for _ in range(2)] for _ in range(4)]
        for d, (dr, dc) in enumerate(dirs):
            rows = range(n - 1, -1, -1) if dr == 1 else range(n)
            cols = range(m - 1, -1, -1) if dc == 1 else range(m)
            for i in rows:
                for j in cols:
                    q = i * m + j
                    ni, nj = i + dr, j + dc
                    nxt = ni * m + nj if 0 <= ni < n and 0 <= nj < m else -1
                    for p, value in enumerate((2, 0)):
                        if grid[i][j] == value:
                            straight[d][p][q] = 1 + (straight[d][1-p][nxt] if nxt >= 0 else 0)

        turned = [[bytearray(size) for _ in range(2)] for _ in range(4)]
        for d, (dr, dc) in enumerate(dirs):
            td = (d + 1) % 4
            rows = range(n - 1, -1, -1) if dr == 1 else range(n)
            cols = range(m - 1, -1, -1) if dc == 1 else range(m)
            tdr, tdc = dirs[td]
            for i in rows:
                for j in cols:
                    q = i * m + j
                    ni, nj = i + dr, j + dc
                    nxt = ni * m + nj if 0 <= ni < n and 0 <= nj < m else -1
                    ti, tj = i + tdr, j + tdc
                    turn_nxt = ti * m + tj if 0 <= ti < n and 0 <= tj < m else -1
                    for p, value in enumerate((2, 0)):
                        if grid[i][j] == value:
                            a = turned[d][1-p][nxt] if nxt >= 0 else 0
                            b = straight[td][1-p][turn_nxt] if turn_nxt >= 0 else 0
                            turned[d][p][q] = 1 + max(a, b)

        answer = 0
        for i in range(n):
            for j in range(m):
                if grid[i][j] == 1:
                    for d, (dr, dc) in enumerate(dirs):
                        ni, nj = i + dr, j + dc
                        length = 1
                        if 0 <= ni < n and 0 <= nj < m:
                            length += turned[d][0][ni * m + nj]
                        answer = max(answer, length)
        return answer

