from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        remaining = list(range(1, n + 1))
        answer = []
        previous_parity = None

        for pos in range(n):
            selected = False
            for i, value in enumerate(remaining):
                parity = value & 1
                if previous_parity is not None and parity == previous_parity:
                    continue

                odd_left = sum(v & 1 for v in remaining) - (parity == 1)
                even_left = len(remaining) - 1 - odd_left
                suffix_len = n - pos - 1

                if suffix_len:
                    next_parity = 1 - parity
                    needed_next = (suffix_len + 1) // 2
                    needed_other = suffix_len // 2
                    if next_parity == 1:
                        if odd_left != needed_next or even_left != needed_other:
                            continue
                    else:
                        if even_left != needed_next or odd_left != needed_other:
                            continue
                elif odd_left or even_left:
                    continue

                completions = fact[odd_left] * fact[even_left]
                if k > completions:
                    k -= completions
                else:
                    answer.append(value)
                    remaining.pop(i)
                    previous_parity = parity
                    selected = True
                    break

            if not selected:
                return []

        return answer

