class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        half = (n + 1) // 2

        # Powers of ten, indexed by the position from the right.
        power = [1] * n
        for i in range(1, n):
            power[i] = (power[i - 1] * 10) % k

        # The contribution modulo k of each digit in the first half.
        coeff = []
        for i in range(half):
            j = n - 1 - i
            if i == j:
                coeff.append(power[i])
            else:
                coeff.append((power[i] + power[j]) % k)

        # suffix[i] is a bit mask of residues obtainable by positions i onward.
        suffix = [0] * (half + 1)
        suffix[half] = 1  # residue zero
