class Fenwick:
    def __init__(self, n):
        self.n = n
        self.c = [0] * (n + 1)
        self.s = [0] * (n + 1)
    def add(self, i, v):
        i += 1
        while i <= self.n:
            self.c[i] += 1
            self.s[i] += v
            i += i & -i
