class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        first = p.find('*')
        second = p.find('*', first + 1)
        a_pat = p[:first]
        b_pat = p[first + 1:second]
        c_pat = p[second + 1:]

        def occurrences(q):
            if not q:
                return None
            m = len(q)
            prefix = [0] * m
            for i in range(1, m):
                j = prefix[i - 1]
                while j and q[i] != q[j]:
                    j = prefix[j - 1]
                if q[i] == q[j]:
                    j += 1
                prefix[i] = j

            result = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != q[j]:
                    j = prefix[j - 1]
                if ch == q[j]:
                    j += 1
                if j == m:
                    result.append(i - m + 1)
                    j = prefix[j - 1]
            return result

        def next_positions(q):
            if not q:
                return list(range(n + 1))
            positions = occurrences(q)
            result = [n + 1] * (n + 1)
            k = len(positions) - 1
            latest = n + 1
            for i in range(n, -1, -1):
                if k >= 0 and positions[k] == i:
                    latest = positions[k]
                    k -= 1
                result[i] = latest
            return result

        a_positions = occurrences(a_pat)
        b_next = next_positions(b_pat)
        c_next = next_positions(c_pat)
        la, lb, lc = len(a_pat), len(b_pat), len(c_pat)

        starts = a_positions if a_positions is not None else range(n + 1)
        best = n + 1
        for start in starts:
            after_a = start + la
            if after_a > n:
                continue
            b_start = b_next[after_a]
            if b_start > n:
                continue
            after_b = b_start + lb
            if after_b > n:
                continue
            c_start = c_next[after_b]
            if c_start > n:
                continue
            best = min(best, c_start + lc - start)

        return -1 if best == n + 1 else best

