from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)

        postorder = []
        stack = [(0, 0)]
        while stack:
            x, state = stack.pop()
            if state:
                postorder.append(x)
            else:
                stack.append((x, 1))
                for y in reversed(children[x]):
                    stack.append((y, 0))

        text = ''.join(s[x] for x in postorder)

        odd = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 1 if i > right else min(odd[left + right - i], right - i + 1)
            while i - k >= 0 and i + k < n and text[i - k] == text[i + k]:
                k += 1
            odd[i] = k
            if i + k - 1 > right:
                left, right = i - k + 1, i + k - 1

        even = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 0 if i > right else min(even[left + right - i + 1], right - i + 1)
            while i - k - 1 >= 0 and i + k < n and text[i - k - 1] == text[i + k]:
                k += 1
            even[i] = k
            if i + k - 1 > right:
                left, right = i - k, i + k - 1

        size = [1] * n
        for x in postorder:
            if parent[x] >= 0:
                size[parent[x]] += size[x]
        position = [0] * n
        for i, x in enumerate(postorder):
            position[x] = i

        answer = [False] * n
        for x in range(n):
            end = position[x]
            start = end - size[x] + 1
            length = size[x]
            if length & 1:
                answer[x] = odd[(start + end) // 2] >= length // 2 + 1
            else:
                answer[x] = even[(start + end + 1) // 2] >= length // 2
        return answer

