import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        length = len(str(n))
        if len(str(m)) != length:
            return -1

        limit = 10 ** length
        prime = [True] * limit
        prime[0] = False
        if limit > 1:
            prime[1] = False
        p = 2
        while p * p < limit:
            if prime[p]:
                for v in range(p * p, limit, p):
                    prime[v] = False
            p += 1

        if prime[n] or prime[m]:
            return -1

        best = {n: n}
        heap = [(n, n)]
        while heap:
            cost, value = heapq.heappop(heap)
            if best.get(value) != cost:
                continue
            if value == m:
                return cost

            digits = list(str(value).zfill(length))
            for pos in range(length):
                old = ord(digits[pos]) - ord('0')
                for change in (-1, 1):
                    new_digit = old + change
                    if not 0 <= new_digit <= 9:
                        continue
                    # Intermediate values retain the original digit count.
                    # Zero itself is a valid one-digit value.
                    if length > 1 and pos == 0 and new_digit == 0:
                        continue
                    next_digits = digits[:]
                    next_digits[pos] = str(new_digit)
                    next_value = int(''.join(next_digits))
                    if prime[next_value]:
                        continue
                    next_cost = cost + next_value
                    if next_cost < best.get(next_value, 10**30):
                        best[next_value] = next_cost
                        heapq.heappush(heap, (next_cost, next_value))

        return -1

