from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i <= right:
                z[i] = min(right - i + 1, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] - 1 > right:
                left, right = i, i + z[i] - 1

        ans = 0
        # First condition: the second piece must have length at least i.
        for i in range(1, n - 1):
            if z[i] >= i:
                ans += max(0, n - 2 * i)

        # For each possible length b of the second piece, compute LCPs
        # along the diagonal (i, i+b), from right to left.
        for b in range(1, n - 1):
            following = 0
            for i in range(n - b - 1, 0, -1):
                current = following + 1 if nums[i] == nums[i + b] else 0
                if current >= b and not (b >= i and z[i] >= i):
                    ans += 1
                following = current
        return ans

