class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        n = len(s)
        active = s.count('1')
        best_gain = 0
        i = 0

        while i < n:
            if s[i] == '0':
                i += 1
                continue

            # Locate this contiguous block of ones.
            j = i
            while j < n and s[j] == '1':
                j += 1

            # It can be traded only when both neighboring blocks are zeros.
            # The augmented ones ensure that endpoint one-blocks do not qualify.
            if i > 0 and j < n:
                left = i - 1
                while left >= 0 and s[left] == '0':
                    left -= 1
                right = j
                while right < n and s[right] == '0':
                    right += 1
                best_gain = max(best_gain, (i - left - 1) + (right - j))

            i = j

        return active + best_gain

