class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        vowel_index = {'a': 0, 'e': 1, 'i': 2, 'o': 3, 'u': 4}

        def at_most(limit: int) -> int:
            if limit < 0:
                return 0
            last = [-1] * 5
            left = 0
            consonants = 0
            total = 0

            for right, ch in enumerate(word):
                index = vowel_index.get(ch)
                if index is None:
                    consonants += 1
                else:
                    last[index] = right

                while consonants > limit:
                    if word[left] not in vowel_index:
                        consonants -= 1
                    left += 1

                earliest_last = min(last)
                if earliest_last >= left:
                    total += earliest_last - left + 1

            return total

        return at_most(k) - at_most(k - 1)

